import heapq
class Solution:
    def getNumberOfBacklogOrders(self, orders):
        buy, sell = [], []
        for price, amount, t in orders:
            if t == 0:
                while amount > 0 and sell and sell[0][0] <= price:
                    sp, sa = heapq.heappop(sell)
                    m = min(amount, sa)
                    amount -= m; sa -= m
                    if sa > 0: heapq.heappush(sell, (sp, sa))
                if amount > 0: heapq.heappush(buy, (-price, amount))
            else:
                while amount > 0 and buy and -buy[0][0] >= price:
                    bp, ba = heapq.heappop(buy)
                    m = min(amount, ba)
                    amount -= m; ba -= m
                    if ba > 0: heapq.heappush(buy, (bp, ba))
                if amount > 0: heapq.heappush(sell, (price, amount))
        MOD = 10**9 + 7
        return (sum(a for _, a in buy) + sum(a for _, a in sell)) % MOD

class Solution:
    def maxValue(self, n, index, maxSum):
        def calc(v, length):
            if v >= length:
                return v * length - length * (length - 1) // 2
            else:
                return v * (v - 1) // 2 + (length - v + 1)
        lo, hi = 1, maxSum
        while lo < hi:
            mid = (lo + hi + 1) // 2
            left = calc(mid, index + 1)
            right = calc(mid, n - index)
            if left + right - mid <= maxSum:
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def countPairs(self, nums, low, high):
        class TrieNode:
            def __init__(self):
                self.ch = [None, None]
                self.cnt = 0
        def insert(root, num):
            node = root
            for i in range(14, -1, -1):
                b = (num >> i) & 1
                if not node.ch[b]: node.ch[b] = TrieNode()
                node = node.ch[b]
                node.cnt += 1
        def query(root, num, limit):
            node, res = root, 0
            for i in range(14, -1, -1):
                if not node: break
                nb = (num >> i) & 1
                lb = (limit >> i) & 1
                if lb:
                    if node.ch[nb]: res += node.ch[nb].cnt
                    node = node.ch[1 - nb]
                else:
                    node = node.ch[nb]
            return res
        root = TrieNode()
        ans = 0
        for x in nums:
            ans += query(root, x, high + 1) - query(root, x, low)
            insert(root, x)
        return ans

class Trie:
    def __init__(self):
        self.children = {}
        self.end_count = 0
        self.pass_count = 0
    def insert(self, word):
        node = self
        for c in word:
            if c not in node.children: node.children[c] = Trie()
            node = node.children[c]
            node.pass_count += 1
        node.end_count += 1
    def countWordsEqualTo(self, word):
        node = self
        for c in word:
            if c not in node.children: return 0
            node = node.children[c]
        return node.end_count
    def countWordsStartingWith(self, prefix):
        node = self
        for c in prefix:
            if c not in node.children: return 0
            node = node.children[c]
        return node.pass_count
    def erase(self, word):
        node = self
        for c in word:
            node = node.children[c]
            node.pass_count -= 1
        node.end_count -= 1

