class Solution:
    def findShortestPath(self, master):
        dirs = {'U':(-1,0),'D':(1,0),'L':(0,-1),'R':(0,1)}
        rev = {'U':'D','D':'U','L':'R','R':'L'}
        grid = {(0,0): master.getGridCost()}
        target = None
        def dfs(r, c):
            nonlocal target
            if master.isTarget(): target = (r, c)
            for d,(dr,dc) in dirs.items():
                nr, nc = r+dr, c+dc
                if (nr,nc) not in grid and master.canMove(d):
                    master.move(d)
                    grid[(nr,nc)] = master.getGridCost()
                    dfs(nr, nc)
                    master.move(rev[d])
        dfs(0, 0)
        if target is None: return -1
        dist = {k: float('inf') for k in grid}
        dist[(0,0)] = 0
        heap = [(0, 0, 0)]
        while heap:
            cost, r, c = heapq.heappop(heap)
            if (r,c) == target: return cost
            if cost > dist[(r,c)]: continue
            for dr,dc in dirs.values():
                nr, nc = r+dr, c+dc
                if (nr,nc) in grid:
                    nd = cost + grid[(nr,nc)]
                    if nd < dist[(nr,nc)]:
                        dist[(nr,nc)] = nd
                        heapq.heappush(heap, (nd, nr, nc))
        return -1

