from functools import lru_cache
class Solution:
    def maxHappyGroups(self, batchSize, groups):
        cnt = [0] * batchSize
        for g in groups: cnt[g % batchSize] += 1
        res = cnt[0]; cnt[0] = 0
        @lru_cache(maxsize=None)
        def dp(remain, state):
            best = 0
            for i in range(1, batchSize):
                if state[i] > 0:
                    ns = list(state); ns[i] -= 1
                    val = (1 if remain == 0 else 0) + dp((remain + i) % batchSize, tuple(ns))
                    best = max(best, val)
            return best
        return res + dp(0, tuple(cnt))

