import bisect
class Solution:
    def minAbsoluteSumDiff(self, nums1, nums2):
        MOD = 10**9 + 7
        sorted1 = sorted(nums1)
        total = sum(abs(a - b) for a, b in zip(nums1, nums2))
        max_imp = 0
        for i in range(len(nums1)):
            cur = abs(nums1[i] - nums2[i])
            if cur == 0: continue
            idx = bisect.bisect_left(sorted1, nums2[i])
            best = cur
            if idx < len(sorted1): best = min(best, abs(sorted1[idx] - nums2[i]))
            if idx > 0: best = min(best, abs(sorted1[idx-1] - nums2[i]))
            max_imp = max(max_imp, cur - best)
        return (total - max_imp) % MOD

