class Solution:
    def minSideJumps(self, obstacles):
        dp = [1, 0, 1]
        for obs in obstacles[1:]:
            if obs: dp[obs-1] = float('inf')
            for i in range(3):
                if i != obs - 1:
                    dp[i] = min(dp[i], min(dp[j]+1 for j in range(3) if j!=i and j!=obs-1))
        return min(dp)

