class Solution:
    def closestRoom(self, rooms, queries):
        rooms.sort(key=lambda x: -x[1])
        q_idx = sorted(range(len(queries)), key=lambda i: -queries[i][1])
        sl = SortedList()
        res = [-1] * len(queries)
        j = 0
        for i in q_idx:
            pref, minSz = queries[i]
            while j < len(rooms) and rooms[j][1] >= minSz:
                sl.add(rooms[j][0])
                j += 1
            if not sl:
                res[i] = -1
                continue
            idx = sl.bisect_left(pref)
            best = -1
            if idx < len(sl):
                best = sl[idx]
            if idx > 0:
                if best == -1 or abs(sl[idx-1]-pref) <= abs(best-pref):
                    best = sl[idx-1]
            res[i] = best
        return res

