class Solution:
    def splitString(self, s):
        def dfs(idx, prev, parts):
            if idx == len(s):
                return parts >= 2
            for i in range(idx + 1, len(s) + 1):
                val = int(s[idx:i])
                if prev == -1 or val == prev - 1:
                    if dfs(i, val, parts + 1):
                        return True
                if prev != -1 and val < prev - 1:
                    break
            return False
        return dfs(0, -1, 0)

