class Solution:
    def maxSumMinProduct(self, nums):
        n = len(nums)
        left, right = [-1]*n, [n]*n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] >= nums[i]:
                right[stack.pop()] = i
            if stack: left[i] = stack[-1]
            stack.append(i)
        prefix = [0] * (n + 1)
        for i in range(n): prefix[i+1] = prefix[i] + nums[i]
        res = 0
        for i in range(n):
            s = prefix[right[i]] - prefix[left[i]+1]
            res = max(res, nums[i] * s)
        return res % (10**9 + 7)

from collections import deque
class Solution:
    def largestPathValue(self, colors, edges):
        n = len(colors)
        adj = [[] for _ in range(n)]
        indeg = [0] * n
        for u, v in edges:
            adj[u].append(v)
            indeg[v] += 1
        dp = [[0]*26 for _ in range(n)]
        queue = deque()
        for i in range(n):
            if indeg[i] == 0:
                queue.append(i)
                dp[i][ord(colors[i])-ord('a')] = 1
        visited = 0
        res = 0
        while queue:
            u = queue.popleft()
            visited += 1
            res = max(res, max(dp[u]))
            for v in adj[u]:
                for c in range(26):
                    dp[v][c] = max(dp[v][c], dp[u][c] + (1 if c == ord(colors[v])-ord('a') else 0))
                indeg[v] -= 1
                if indeg[v] == 0:
                    queue.append(v)
        return res if visited == n else -1

